import {api,token,personal,message,el} from './common.js';
import {initEnvelope} from './envelope.js';
const status=document.querySelector('#rsvp-status'),name=document.querySelector('#guest-name'),actions=document.querySelector('#rsvp-actions');
document.querySelector('#gifts-link').href=personal('/presentes/');
document.querySelector('#money-shortcut').href=personal('/presentes/');
document.querySelector('#messages-link').href=personal('/mensagens/')+'#escrever';document.querySelector('#messages-wall-link').href=personal('/mensagens/');
const whatsapp=document.querySelector('#whatsapp-link');
function wa(guest){const people=guest?[guest.name,...(guest.companion?[guest.companion]:[])]:[];whatsapp.href='https://wa.me/258848675125?text='+encodeURIComponent(`Olá Aniceta! ${people.length>1?'O nosso convite é para '+people.join(' e '):'Sou '+(people[0]||'um convidado')}. Gostaria de falar sobre a confirmação de presença no vosso casamento de 27/02/2027.`)}wa();
async function load(){if(!token){name.textContent='Será uma alegria receber você.';status.textContent='Abra o link pessoal enviado pelos noivos para confirmar a presença.';return}try{const {guest}=await api('/api/invite');name.textContent=guest.companion?`${guest.name} & ${guest.companion}, este convite é para vocês.`:`${guest.name}, este convite é para você.`;const envelopeName=document.querySelector('#envelope-guest');if(envelopeName)envelopeName.textContent=guest.name+(guest.companion?' & '+guest.companion:'');wa(guest);status.textContent='Confirme abaixo a presença de cada pessoa indicada no convite.';actions.hidden=false;actions.replaceChildren();const form=el('form',undefined,'rsvp-form');const inputs={};for(const [key,person,value]of [['rsvp',guest.name,guest.rsvp],...(guest.companion?[['companion_rsvp',guest.companion,guest.companion_rsvp]]:[])]){const label=el('label',person);label.htmlFor='attendance-'+key;const select=el('select');select.id=label.htmlFor;for(const [v,t]of [['pending','Por confirmar'],['yes','Sim, estarei presente'],['no','Não poderei estar presente']]){const o=el('option',t);o.value=v;select.append(o)}select.value=value;inputs[key]=select;form.append(label,select)}const save=el('button','Guardar confirmação');save.type='submit';form.append(save);form.onsubmit=async e=>{e.preventDefault();if(inputs.rsvp.value==='pending'){await message('Seleccione a resposta do primeiro convidado.');return}save.disabled=true;try{await api('/api/rsvp',{method:'POST',body:Object.fromEntries(Object.entries(inputs).map(([k,v])=>[k,v.value]))});await load();await message('Confirmação guardada. Obrigado pelo carinho!')}catch(e){await message(e.message)}finally{save.disabled=false}};actions.append(form)}catch(e){status.textContent=e.message;actions.hidden=true}}load();
const audio=document.querySelector('#wedding-music'),toggle=document.querySelector('#music-toggle');audio.volume=.45;
async function play(){try{await audio.play()}catch{toggle.textContent='♫ Ouvir música'}}
audio.addEventListener('play',()=>toggle.textContent='Ⅱ Pausar música');audio.addEventListener('pause',()=>toggle.textContent='♫ Ouvir música');audio.addEventListener('error',()=>{toggle.textContent='Música indisponível';toggle.disabled=true});toggle.onclick=()=>audio.paused?play():audio.pause();
initEnvelope(play);

function updateCountdown(){const box=document.querySelector('#wedding-countdown');if(!box)return;const difference=new Date('2027-02-27T09:00:00+02:00').getTime()-Date.now();if(difference<=0){box.replaceChildren(el('span','Chegou o nosso grande dia!'));return}const minutes=Math.floor(difference/60000),values=[[Math.floor(minutes/1440),'dias'],[Math.floor(minutes/60)%24,'horas'],[minutes%60,'minutos']];box.replaceChildren(...values.map(([value,label])=>{const item=el('span');item.append(el('strong',String(value).padStart(2,'0')),el('small',label));return item}))}updateCountdown();setInterval(updateCountdown,60000);

const moneyDialog=document.querySelector('#money-dialog');if(moneyDialog&&typeof moneyDialog.showModal==='function'){let previousMoneyOverflow='';for(const id of ['gifts-link','money-shortcut']){const link=document.getElementById(id);if(link)link.addEventListener('click',e=>{e.preventDefault();if(!moneyDialog.open){previousMoneyOverflow=document.body.style.overflow;moneyDialog.querySelector('#money-copy-status').textContent='';moneyDialog.showModal();document.body.style.overflow='hidden'}})}moneyDialog.addEventListener('close',()=>{document.body.style.overflow=previousMoneyOverflow});moneyDialog.addEventListener('click',e=>{if(e.target!==moneyDialog)return;const r=moneyDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)moneyDialog.close()});for(const b of moneyDialog.querySelectorAll('[data-copy-payment]'))b.onclick=async()=>{const status=moneyDialog.querySelector('#money-copy-status');try{await navigator.clipboard.writeText(b.dataset.copyPayment);status.textContent='Dados copiados com sucesso.'}catch{status.textContent='Seleccione e copie este número: '+b.dataset.copyPayment}};}
